cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');

// Check support_tickets or any escalation-related tables
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('All tables:', tables.map(t => t.name));

// Check if there's a tickets table in world.db
for (const t of tables.map(r => r.name)) {
  const info = db.prepare('PRAGMA table_info(' + t + ')').all();
  if (info.some(c => c.name.includes('ticket') || c.name.includes('escalat') || c.name.includes('transfer') || c.name.includes('agent'))) {
    console.log(t + ' columns:', info.map(c => c.name));
  }
}
"
